package com.techie345.moneys.financial.rule;
import java.util.UUID; import com.techie345.moneys.financial.*; import jakarta.persistence.*;
@Entity @Table(name="merchant_rule") public class RuleEntity extends FinancialEntity { @Column(nullable=false) String pattern; @Column(nullable=false) String category; UUID accountId; @Enumerated(EnumType.STRING) TransactionKind kind; protected RuleEntity(){} public RuleEntity(UUID o,String p,String c,UUID a,TransactionKind k){ownerId=o;pattern=p;category=c;accountId=a;kind=k;} public String getPattern(){return pattern;} public String getCategory(){return category;} public UUID getAccountId(){return accountId;} public TransactionKind getKind(){return kind;} public void update(String p,String c,UUID a,TransactionKind k){pattern=p;category=c;accountId=a;kind=k;} }
